 if(!$errors){$st=db()->prepare('INSERT INTO settings (setting_key,setting_value) VALUES (:k,:v) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach($values as $k=>$v)$st->execute(['k'=>$k,'v'=>$v]);flash('success','Pengaturan website berhasil disimpan.');redirect('settings.php');}
